7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
8	
9	/**
10	 * The duplicate check for creating owners, now keyed on the household. The household is
11	 * {@code (normalizedLastName, postcode)} expressed as a deterministic {@code householdId} (see
12	 * {@link OwnerIdentityKey#householdId(String, String)}), so owners sharing a last name and postcode
13	 * are the same household. A create request whose computed household id matches an existing owner's is
14	 * rejected with 409 via {@link DuplicateOwnerException}.
15	 *
16	 * <p>Setting {@code sharesHousehold} true bypasses this block: the owner is then created as a declared
17	 * household member (and, being declared, is not flagged as a possible duplicate by
18	 * {@link AssignPossibleDuplicate}). Runs before {@link BuildOwner}.
19	 */
20	public class EnsureUniqueIdentity {
21	
22	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
23	            throws DuplicateOwnerException {
